# Define the means function
def arithmetic_mean(x, y):
    return (x + y) / 2

def harmonic_mean(x, y):
    # Assuming x and y are non-zero
    return 2 * x * y / (x + y)

# Test small pairs (m, n) where gcd(m, n) = 1
# We stop after a few iterations as the state space can grow rapidly.
# The goal is to see if 1 appears quickly.

pairs_to_test = [
    (1, 1), # Trivial case (m=n=1, m+n=2)
    (2, 1), # m/n = 2. Start: {2, 0.5}
    (3, 1), # m/n = 3. Start: {3, 1/3}
    (3, 2), # m/n = 1.5. Start: {1.5, 2/3}
    (4, 1), # m/n = 4. Start: {4, 0.25}
    (5, 2) # m/n = 2.5. Start: {2.5, 0.4}
]

print("--- Testing Small Pairs ---")

for m, n in pairs_to_test:
    if m == n:
        print(f"({m}, {n}): Trivial case. 1 is present.")
        continue

    x = m / n
    y = n / m

    # State is represented by a set of numbers on the board
    board = {x, y}

    # Limit iterations to prevent infinite loops during simulation
    for step in range(10):
        current_numbers = list(board)

        if 1.0 in board:
            print(f"({m}, {n}): Found 1 in {step} steps.")
            break

        # Try combining all unique pairs on the board
        generated = set()
        new_board = set(current_numbers)

        for i in range(len(current_numbers)):
            for j in range(i + 1, len(current_numbers)):
                a = current_numbers[i]
                b = current_numbers[j]

                # Add AM
                z_am = arithmetic_mean(a, b)
                generated.add(z_am)

                # Add HM
                if a + b != 0:
                    z_hm = harmonic_mean(a, b)
                    generated.add(z_hm)

        # Add new numbers to the board for the next step, ensuring we don't infinitely duplicate
        # For this simulation, we only add the *first* set of generated numbers.
        if not generated:
             break

        new_board.update(generated)
        board = new_board

        if len(board) > 100: # Safety break for explosion
            break
    else:
        if 1.0 not in board:
            print(f"({m}, {n}): 1 not found within 10 steps (or state exploded).")

